    const rest = node.position.y;
    let strength = 1;
    let elapsed = 0; // seconds

    const task = createAnimationTask((mgr, deltaMs) => {
        elapsed += deltaMs / 1000;
        // Period is 1 second: 0.5s up, 0.5s down
        const phase = elapsed % 1;
        // Triangular wave: 0→1 in first half, 1→0 in second half
        const wave = phase < 0.5 ? phase * 2 : (1 - phase) * 2;
        node.position.y = rest + strength * 0.5 * wave;
    });

    addAnimationTask(manager, task);

    return (s: number) => {
        strength = s;
    };
